  ayudaAtajoGuias: "See tour guides",
  ayudaAtajoTutorial: "Start the tutorial",
  faqViajerosTitulo: "FAQ — Travellers",
  faq1q: "How do I search for a destination on KAVARI?",
  faq1a: "On the Destinations page you will find the 21 countries available on KAVARI. Use the search bar at the top to filter by country or city name. Click “View destination” to access all the tourist information for that country: culture, gastronomy, adventure, airlines, accommodation and more.",
  faq2q: "Can I hire a tour guide through KAVARI?",
  faq2a: "Yes. Within each country page you will find the “Tour Guides” section listing the certified guides available for that destination. Filter by level (Diamond, Gold, Silver) and click “Hire” to send your request directly to the guide.",
  faq3q: "Are the prices shown final?",
  faq3a: "Airline and accommodation prices are reference prices for mid-season. Final prices may vary depending on dates, availability and flight origin. When you click “Book flight” or “See options in the area”, you will be redirected directly to the airline or Airbnb listing to confirm the final price.",
  faq4q: "What practical information can I find about each country?",
  faq4a: "In the “Practical info” section of each country you will find: local currency, official language, visas and required documents, transport, Wi-Fi connectivity, best seasons to travel and a suggested itinerary. You can also use the AI Assistant to ask specific questions about the destination.",
  faq5q: "How does the KAVARI AI Assistant work?",
  faq5a: "Each country page has a chatbot specialised in that destination. You can ask it about weather, visas, safety, gastronomy, costs, transport, emergencies and more. The assistant answers with information specific to the selected country. Use the preset suggestions to start or type your own question.",
  faqGuiasTitulo: "FAQ — Tour guides",
  faq6q: "How do I register as a tour guide on KAVARI?",
  faq6a: "Click the “I'm a Guide” button on the home page or visit the Guides section and select “Join as a guide”. Complete your profile with your name, description, languages, specialties, and the city and country where you work. Choose your membership level (Silver, Gold or Diamond) and make the payment to activate your profile.",
  faq7q: "What are the differences between the Silver, Gold and Diamond levels?",
  faq7a: "<strong>Silver ($20/month):</strong> Standard visibility in guide listings. <br><strong>Gold ($35/month):</strong> Higher ranking in search results, featured profile. <br><strong>Diamond ($50/month):</strong> Top priority in listings, special badge, appears first to travellers. Diamond and Gold guides are listed ahead of Silver guides.",
  faq8q: "In which countries can I register as a guide?",
  faq8a: "You can register as a guide for any of the 21 destinations available on KAVARI. When you select your country during registration, your profile will automatically appear in that country's “Tour Guides” section. If you operate in several countries, you can create separate profiles for each one.",
  faq9q: "What payment methods does KAVARI accept?",
  faq9a: "To pay for guide memberships we accept: Yappy (Panama mobile banking), bank transfer (Banco General, BAC, Banistmo) and credit/debit card (Visa, Mastercard, American Express). All payments are protected with SSL encryption.",
  faqPlataformaTitulo: "FAQ — The platform",
  faq10q: "Which languages is KAVARI available in?",
  faq10a: "KAVARI est disponible en espagnol, anglais, portugais et français. Vous pouvez changer de langue à tout moment via le sélecteur de langue (icône 🌐) présent dans la barre de navigation de toutes les pages. Votre préférence est enregistrée automatiquement pour votre prochaine visite.",
  faq11q: "How do I activate dark mode?",
  faq11a: "Click the 🌙 icon on any KAVARI navigation bar to activate dark mode. You can also tap the ☀️ icon to switch back to light mode. Your preference is saved automatically and applied across all pages of the platform.",
  faq12q: "How does the platform tutorial work?",
  faq12a: "The interactive tutorial appears automatically the first time you visit KAVARI. It guides you step by step through all the platform's features with pop-up messages, arrows and examples. To watch it again, click the “Tutorial” button in the main menu of the home page.",
  faqPaquetesTitulo: "FAQ — Travel packages",
  faq13q: "What does a KAVARI travel package include?",
  faq13a: "Every package is different, but they generally include: international flight (on international packages), 3- or 4-star hotel, airport-hotel transfers, certified tour guide, daily breakfast and entrance to the main attractions. Click “View details” on any package to see exactly what that itinerary includes.",
  faq14q: "Can I book directly from KAVARI?",
  faq14a: "KAVARI currently works as an information platform and travel directory. When you click “Book now” you will be taken to the full destination page to coordinate with local guides. For flight and hotel bookings, links take you directly to the airlines and to Airbnb. For full packages, contact us through the Contact form.",
