  paisPeru_cultura_items_danzatijeras_tag: "Danse traditionnelle · Andine",
  paisPeru_cultura_items_danzatijeras_descripcion: "Danse rituelle des Andes centrales, reconnue pour sa force symbolique et son énergie.",
  paisPeru_cultura_items_danzatijeras_detalle: "Déclarée Patrimoine culturel immatériel de l'humanité par l'UNESCO. Les danseurs utilisent des ciseaux.",
  paisPeru_cultura_items_intiraymi_tag: "Fête · Inca",
