  paisPeru_cultura_items_intiraymi_detalle: "Instituée par Pachacútec. Interdite par les Espagnols, elle fut restaurée en 1944.",
  paisPeru_cultura_items_musicaandina_tag: "Musique · Tradition vivante",
  paisPeru_cultura_items_musicaandina_descripcion: "Expression musicale avec instruments comme la zampoña, la quena, le charango et le bombo.",
  paisPeru_cultura_items_musicaandina_detalle: "Le charango est originaire de l'altiplano péruvo-bolivien. La marinera est la danse nationale.",
  paisPeru_cultura_items_cocinaperuana_tag: "Gastronomie · UNESCO",
  paisPeru_cultura_items_cocinaperuana_descripcion: "Fusion des traditions côtières, andines et amazoniennes. Reconnue internationalement.",
  paisPeru_cultura_items_cocinaperuana_detalle: "Le Pérou détient le record Guinness de la plus grande variété de plats typiques.",
